def placeholder_scan(sql):
    positions = []
    in_quote = False
    i = 0
    s = sql
    while i < len(s):
        ch = s[i]
        if in_quote:
            if ch == "'":
                # Check for escaped quote
                if i + 1 < len(s) and s[i+1] == "'":
                    i += 2
                    continue
                else:
                    in_quote = False
                    i += 1
            else:
                i += 1
        else:
            if ch == "'":
                in_quote = True
                i += 1
            elif ch == "?":
                positions.append(i)
                i += 1
            else:
                i += 1
    return positions
